import{_ as a,o as n,a as p,b as e}from"./app.DKoEZOcr.js";const l="/ascendc.github.io/pr/5487/assets/sk_dcci.C569GLtm.png",c="/ascendc.github.io/pr/5487/assets/set_next.BDAxJyEP.png",t="/ascendc.github.io/pr/5487/assets/wait_pre.BSHp4Ocf.png",m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"SuperKernel","link":"/guide/programming_guide/advanced_programming/super_kernel/principles"},{"text":"算子适配说明","link":"/guide/programming_guide/advanced_programming/super_kernel/operator_adaptation"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/super_kernel/operator_adaptation.md","filePath":"guide/programming_guide/advanced_programming/super_kernel/operator_adaptation.md","outlineHeaders":[{"level":2,"title":"全核同步约束","slug":"全核同步约束","link":"#全核同步约束"},{"level":2,"title":"MIX 1:1算子核数比例约束","slug":"MIX-1:1算子核数比例约束","link":"#MIX-1:1算子核数比例约束"},{"level":2,"title":"标量读写与Cache一致性","slug":"标量读写与Cache一致性","link":"#标量读写与Cache一致性"},{"level":2,"title":"核数获取接口约束","slug":"核数获取接口约束","link":"#核数获取接口约束"},{"level":2,"title":"TPipe析构约束","slug":"TPipe析构约束","link":"#TPipe析构约束"},{"level":2,"title":"性能优化建议","slug":"性能优化建议","link":"#性能优化建议"},{"level":2,"title":"核函数（Kernel）直调算子的额外适配","slug":"核函数（Kernel）直调算子的额外适配","link":"#核函数（Kernel）直调算子的额外适配"}],"lastUpdated":1787050286000}'),r={name:"guide/programming_guide/advanced_programming/super_kernel/operator_adaptation.md"};function i(o,s,d,h,u,_){return n(),p("div",null,[...s[0]||(s[0]=[e(`<div><article class="markdown-body"><h1>算子适配说明</h1><p>自定义算子要支持融合进SuperKernel，开发流程上与普通算子并无显著差异，但需要遵循以下一系列<strong>特定约束</strong>。这些约束与具体的开启方式（npugraph_ex后端或GE图模式）无关，大部分约束与算子启动核数（block num）以及SuperKernel启动核数之间的关系相关，需要开发者在算子设计阶段就予以关注。</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>SuperKernel启动核数为其中所有子核函数（Kernel）的最大启动核数。例如，SuperKernel包含算子a（启动核数为4）和算子b（启动核数为2），则SuperKernel启动核数为4。</p></div><h2 id="全核同步约束">全核同步约束<a class="header-anchor" href="#全核同步约束">​</a></h2><p>自定义算子若进行全核同步，需注意该子核函数（Kernel）启动的核数需要与SuperKernel的核数一致，通常需要启动当前硬件满核。若子核函数（Kernel）启动的核数少于SuperKernel的核数，全核同步会等待所有核完成，导致卡住超时。</p><h2 id="MIX-1:1算子核数比例约束">MIX 1:1算子核数比例约束<a class="header-anchor" href="#MIX-1:1算子核数比例约束">​</a></h2><p>若自定义算子的核函数（Kernel）类型设置为<code>KERNEL_TYPE_MIX_AIC_1_1</code>，因为SuperKernel会根据启动核数等信息调整SuperKernel的启动比例，此时需特别注意该算子也可以适应SuperKernel的1:2启动比例，确保AIC与AIV之间的硬同步操作正确执行。比如：</p><ul><li>算子内部使用了AIC与AIV之间的硬同步接口（CrossCoreSetFlag和CrossCoreWaitFlag），不要单独指定某些AIV核调用硬同步接口，要使所有AIV核均调用硬同步接口，防止因为硬同步数量不匹配而导致卡死超时。</li><li>使用Matmul高阶API时，算子逻辑应保证仅有一个AIV0核调用Matmul接口，防止启动两个AIV核之后出现AIV1核消息无法接收导致卡死超时。</li></ul><h2 id="标量读写与Cache一致性">标量读写与Cache一致性<a class="header-anchor" href="#标量读写与Cache一致性">​</a></h2><p>在开发自定义算子时，开发者必须确保所有对GM的标量读写操作都按需正确插入<a href="../../../../api/SIMD-API/basic_api/cache_control/DataCacheCleanAndInvalid.html">DataCacheCleanAndInvalid</a>指令。</p><ul><li>在单算子编译场景下，毕昇编译器自动在算子末尾添加DataCacheCleanAndInvalid指令，刷新整个DCache（数据缓存）。</li><li>在SuperKernel中，子核函数（Kernel）被当作普通函数处理，编译器不会自动插入该指令来确保数据缓存一致性，开发者需要自行保证，避免因容错机制改变而导致错误。</li></ul><p>出于性能考虑，SuperKernel场景下Cache刷新机制如下：</p><ul><li><p>如果开发者调用GlobalTensor的<a href="../../../../api/SIMD-API/basic_api/data_structures/GlobalTensor/GetValue.html"><code>GetValue</code></a>和<a href="../../../../api/SIMD-API/basic_api/data_structures/GlobalTensor/SetValue.html"><code>SetValue</code></a>接口对GM进行标量读写，在GE入图及npugraph_ex后端aclnn调用场景，SuperKernel编译时会自动在两个接口内部插入DataCacheCleanAndInvalid指令刷新单个Cache Line，保证一定的数据缓存一致性。不会在子核函数（Kernel）调用前后插入DataCacheCleanAndInvalid。</p></li><li><p>如果开发者通过GlobalTensor的<code>()</code>运算符接口来获取值（读值时会插入DataCacheCleanAndInvalid指令刷新单个Cache Line保证数据缓存一致性），但通过该接口直接改写了GlobalTensor对应位置的值时，则不会自动插入DataCacheCleanAndInvalid指令，开发者需要自行保证数据缓存一致性。例如：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="w"> </span><span class="n">xGm</span><span class="p">;</span>
<span class="n">xGm</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">((</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="o">*</span><span class="p">)(</span><span class="n">addr</span><span class="p">),</span><span class="w"> </span><span class="n">length</span><span class="p">);</span><span class="w"> </span><span class="c1">// addr为GM地址，length为对应GM长度</span>
<span class="n">xGm</span><span class="p">(</span><span class="mi">0</span><span class="p">)</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="kt">float</span><span class="p">)(</span><span class="mf">1.0</span><span class="p">);</span><span class="w"> </span><span class="c1">// 在获取值时，SuperKernel能够保证自动刷新cache line，但是写值时，相当于普通变量直接赋值，SuperKernel无法插入DataCacheCleanAndInvalid，需要用户保证数据缓存的一致性。</span>
</code></pre></div></li></ul><p>对于频繁调用<code>GetValue</code>和<code>SetValue</code>的算子，建议使用<code>dcci_before_kernel_start</code>、<code>dcci_after_kernel_end</code>关闭指定算子内<code>GetValue</code>/<code>SetValue</code>中自动插入的缓存刷新指令，而改为算子调用前后插入整个DCache刷新，避免性能劣化。具体option说明，请参考各自PyTorch图模式SuperKernel文档option说明章节：GE入图参考<a href="https://www.hiascend.com/document/detail/zh/Pytorch/latest/devguide/TorchAir/docs/zh/ascend_ir/features/advanced/super_kernel_scope.md">图内标定SuperKernel范围</a>，npugraph_ex后端参考<a href="https://www.hiascend.com/document/detail/zh/Pytorch/latest/devguide/TorchAir/docs/zh/npugraph_ex/advanced/superkernel.md">SuperKernel功能</a>中<code>super_kernel_optimize_options</code>参数说明。</p><p>Cache刷新机制示意图如下图所示：</p><p><img src="`+l+`" alt></p><h2 id="核数获取接口约束">核数获取接口约束<a class="header-anchor" href="#核数获取接口约束">​</a></h2><p>在GE入图及npugraph_ex后端aclnn调用场景，子核函数（Kernel）中调用<a href="../../../../api/SIMD-API/basic_api/tool_interface/system_resources_and_variables/GetBlockNum.html">GetBlockNum</a>接口获取核数时，无论是否融合SuperKernel，获取的核数保持不变，不受SuperKernel启动核数的影响。因此，在使用该接口时，开发者无需特别关注SuperKernel的启动核数，使用方法和开发普通算子时一样。</p><p>在SuperKernel场景下，如下Ascend C API在算子编译过程中适配了SuperKernel，子算子需要严格按照Ascend C提供的API进行编程，从而无需感知是否开启SuperKernel。例如在获取核数和索引时，<strong>不能调用<code>block_idx</code>、<code>block_num</code>等底层变量和相关API</strong>，必须使用下表中的Ascend C API：</p><table><thead><tr><th>API列表</th><th>功能描述</th></tr></thead><tbody><tr><td><a href="../../../../api/SIMD-API/basic_api/tool_interface/system_resources_and_variables/GetBlockIdx.html">AscendC::GetBlockIdx()</a></td><td>获取当前核的index</td></tr><tr><td><a href="../../../../api/SIMD-API/basic_api/tool_interface/system_resources_and_variables/GetBlockNum.html">AscendC::GetBlockNum()</a></td><td>获取当前任务配置的核数</td></tr></tbody></table><div data-filter="A3,910b"><h2 id="TPipe析构约束">TPipe析构约束<a class="header-anchor" href="#TPipe析构约束">​</a></h2><p>针对Atlas A2 训练系列产品/Atlas A2 推理系列产品、Atlas A3 训练系列产品/Atlas A3 推理系列产品，在GE入图及npugraph_ex后端aclnn调用场景，子算子TPipe对象析构（<a href="../../../../api/SIMD-API/basic_api/resource_management/TPipe/Destroy.html">TPipe::Destroy</a>）接口内部的<code>AscendC::PipeBarrier&lt;PIPE_ALL&gt;()</code>指令会被去除，如果算子内部使用了多个TPipe对象或手动调用Destroy函数时开发者需自行保障TPipe对象间流水的同步。</p><p>样例：</p><ul><li><p><strong>场景一：TPipe对象析构时同步</strong></p><p>当算子中存在多个TPipe对象，且通过作用域（大括号或算子结束）触发析构时，需在第一个TPipe析构后手动插入<code>PipeBarrier&lt;PIPE_ALL&gt;()</code>，确保流水同步。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 场景一：两个TPipe对象通过作用域析构，需在第一个析构后插入PipeAll</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPipe</span><span class="w"> </span><span class="n">pipe1</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">TQue</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">VECOUT</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="o">&gt;</span><span class="w"> </span><span class="n">que1</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">num1</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">len1</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span>
<span class="w">    </span><span class="n">pipe1</span><span class="p">.</span><span class="n">InitBuffer</span><span class="p">(</span><span class="n">que1</span><span class="p">,</span><span class="w"> </span><span class="n">num1</span><span class="p">,</span><span class="w"> </span><span class="n">len1</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// ... 使用pipe1进行算子计算 ...</span>
<span class="p">}</span><span class="w"> </span><span class="c1">// pipe1析构，但Destroy中的PipeBarrier已被去除</span>

<span class="c1">// 必须手动插入PipeAll，保证pipe1流水完成后再使用pipe2</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">PipeBarrier</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">PIPE_ALL</span><span class="o">&gt;</span><span class="p">();</span>

<span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPipe</span><span class="w"> </span><span class="n">pipe2</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">TQue</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">VECOUT</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="o">&gt;</span><span class="w"> </span><span class="n">que2</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">num2</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">len2</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span>
<span class="w">    </span><span class="n">pipe2</span><span class="p">.</span><span class="n">InitBuffer</span><span class="p">(</span><span class="n">que2</span><span class="p">,</span><span class="w"> </span><span class="n">num2</span><span class="p">,</span><span class="w"> </span><span class="n">len2</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// ... 使用pipe2进行算子计算 ...</span>
<span class="p">}</span><span class="w"> </span><span class="c1">// pipe2析构</span>
</code></pre></div></li><li><p><strong>场景二：手动调用Destroy时同步</strong></p><p>当算子中存在多个TPipe对象，且手动调用<code>Destroy</code>接口时，需在第一个TPipe的<code>Destroy</code>调用后手动插入<code>PipeBarrier&lt;PIPE_ALL&gt;()</code>，确保流水同步。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 场景二：两个TPipe对象手动调用Destroy，需在第一个Destroy后插入PipeAll</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">TPipe</span><span class="w"> </span><span class="n">pipe1</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">TQue</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">VECOUT</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="o">&gt;</span><span class="w"> </span><span class="n">que1</span><span class="p">;</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">num1</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">len1</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span>
<span class="n">pipe1</span><span class="p">.</span><span class="n">InitBuffer</span><span class="p">(</span><span class="n">que1</span><span class="p">,</span><span class="w"> </span><span class="n">num1</span><span class="p">,</span><span class="w"> </span><span class="n">len1</span><span class="p">);</span>
<span class="c1">// ... 使用pipe1进行算子计算 ...</span>
<span class="n">pipe1</span><span class="p">.</span><span class="n">Destroy</span><span class="p">();</span><span class="w"> </span><span class="c1">// Destroy中的PipeBarrier已被去除</span>

<span class="c1">// 必须手动插入PipeAll，保证pipe1流水完成后再使用pipe2</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">PipeBarrier</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">PIPE_ALL</span><span class="o">&gt;</span><span class="p">();</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">TPipe</span><span class="w"> </span><span class="n">pipe2</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">TQue</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">VECOUT</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="o">&gt;</span><span class="w"> </span><span class="n">que2</span><span class="p">;</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">num2</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">len2</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span>
<span class="n">pipe2</span><span class="p">.</span><span class="n">InitBuffer</span><span class="p">(</span><span class="n">que2</span><span class="p">,</span><span class="w"> </span><span class="n">num2</span><span class="p">,</span><span class="w"> </span><span class="n">len2</span><span class="p">);</span>
<span class="c1">// ... 使用pipe2进行算子计算 ...</span>
<span class="n">pipe2</span><span class="p">.</span><span class="n">Destroy</span><span class="p">();</span>
</code></pre></div></li></ul></div><h2 id="性能优化建议">性能优化建议<a class="header-anchor" href="#性能优化建议">​</a></h2><ul><li><p><strong>任务间同步</strong></p><p>开发者在进行核函数（Kernel）侧编程时，可以通过调用<a href="../../../../api/SIMD-API/basic_api/sync_control/inter_task_sync/SetNextTaskStart.html">SetNextTaskStart</a>和<a href="../../../../api/SIMD-API/basic_api/sync_control/inter_task_sync/WaitPreTaskEnd.html">WaitPreTaskEnd</a>两个任务间接口，进一步提升性能。</p><ul><li>调用<code>SetNextTaskStart</code>后的指令可以和后续其他的子核函数（Kernel）实现并行，提升整体性能。如<a href="#fig37581010773">图1</a>所示，SuperKernel按序调用子核函数（Kernel），为保证子核函数（Kernel）之间数据互不干扰，会在子核函数（Kernel）间插入算子间同步进行保序，子核函数（Kernel）<sub>N-1</sub>调用该接口后，之后的指令会和后续子核函数（Kernel）<sub>N</sub>实现并行。</li></ul><p><strong>图1</strong> 通过SetNextTaskStart实现并行示意图<span id="fig37581010773"></span><br><img src="`+c+'" alt title="通过SetNextTaskStart实现并行示意图"></p><ul><li>调用<code>WaitPreTaskEnd</code>前的指令可以和前序其他的子核函数（Kernel）实现并行，提升整体性能。如<a href="#fig99271836191110">图2</a>所示，SuperKernel按序调用子核函数（Kernel），为保证子核函数（Kernel）之间数据互不干扰，会在子核函数（Kernel）间插入算子间同步进行保序，子核函数（Kernel）<sub>N+1</sub>调用该接口之前的指令会和前序子核函数（Kernel）<sub>N</sub>实现并行。</li></ul><p><strong>图2</strong> 通过WaitPreTaskEnd实现并行示意图<span id="fig99271836191110"></span><br><img src="'+t+'" alt title="通过WaitPreTaskEnd实现并行示意图"></p></li><li><p><strong>二进制复用优化</strong></p><p>在GE入图Tiling下沉场景下，可以通过<code>--op_relocatable_kernel_binary</code>编译选项，开启二进制复用优化，提升编译性能，具体可参考<a href="../aclnn_operator_development/compilation_and_deployment/basic_process.html">算子工程编译</a>。</p></li></ul><h2 id="核函数（Kernel）直调算子的额外适配">核函数（Kernel）直调算子的额外适配<a class="header-anchor" href="#核函数（Kernel）直调算子的额外适配">​</a></h2><p>对于使用<code>&lt;&lt;&lt;&gt;&gt;&gt;</code>方式开发的Ascend C算子，目前仅支持在npugraph_ex后端融合进SuperKernel。此类算子除需遵循上述通用约束外，还需要在算子kernel入口侧增加SuperKernel入口函数。具体方法请参考<a href="kernel_direct_call_adaptation.html">核函数（Kernel）直调算子额外适配说明</a>。</p></article></div>',1)])])}const A=a(r,[["render",i]]);export{m as __pageData,A as default};
